"""配置生成与健康判断测试；网络与系统服务调用均为模拟。"""
import contextlib
import copy
import importlib.util
import io
import os
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest
from unittest import mock
import yaml

ROOT = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location("ha_configure", ROOT / "ha-configure.py")
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)


class HaTests(unittest.TestCase):
    def setUp(self):
        self.local = ROOT / ".local"
        self.local.mkdir(exist_ok=True)
        self.temp = tempfile.TemporaryDirectory(dir=self.local)
        self.addCleanup(self.temp.cleanup)
        self.directory = Path(self.temp.name)
        self.data = yaml.safe_load((ROOT / "ha.sample.yaml").read_text())

    def load(self, data=None):
        path = self.directory / "ha.yaml"
        path.write_text(yaml.safe_dump(self.data if data is None else data))
        return module.load_config(path, "node-a")

    def health(self, overrides=None):
        spec = {"policy": "all", "round_timeout": 2, "checks": self.load()["health"]["checks"]}
        spec.update(overrides or {})
        namespace = {"__name__": "health_test", "SPEC": spec}
        exec(compile(module.HEALTH_PROGRAM, "health.py", "exec"), namespace)
        return namespace

    def test_nodes_and_nopreempt(self):
        data = self.load()
        config, runtime, name = module.render(data, "node-a", Path("/etc/keepalived"))
        self.assertIn("unicast_src_ip 192.168.10.11", config)
        self.assertIn("        192.168.10.12", config)
        self.assertIn("nopreempt", config)
        self.assertIn("weight 0", config)
        self.assertIn("init_fail", config)
        self.assertIn(name, config)
        self.assertIn("script \"/etc/keepalived/" + name + " --quiet\"", config)
        self.assertTrue(runtime.startswith("#!" + str(Path(module.sys.executable).resolve())))
        self.assertIn("        192.168.10.100/24\n", config)
        self.assertNotIn("192.168.10.100/24 dev eth0", config)
        compile(runtime, name, "exec")
        backup = module.render(data, "node-b", Path("/etc/keepalived"))[0]
        self.assertIn("priority 100", backup)
        self.assertIn("        192.168.10.11", backup)

    def test_three_nodes_equal_priority(self):
        self.data["nodes"]["node-a"]["priority"] = 100
        self.data["nodes"]["node-c"] = {
            "address": "192.168.10.13", "interface": "eth0", "priority": 100}
        data = self.load()
        for name in data["nodes"]:
            config = module.render(data, name, Path("/etc/keepalived"))[0]
            self.assertIn("    priority 100\n", config)
            for peer_name, peer in data["nodes"].items():
                if peer_name != name:
                    self.assertIn("        " + peer["address"] + "\n", config)

    def test_preempt(self):
        self.data["vrrp"]["preempt"] = True
        self.assertNotIn("    nopreempt\n", module.render(self.load(), "node-a", Path("/etc/keepalived"))[0])

    def test_unknown_field(self):
        self.data["health"]["falls"] = 3
        with self.assertRaises(ValueError):
            self.load()

    def test_duplicate_yaml_keys(self):
        path = self.directory / "duplicate.yaml"
        path.write_text("version: 1\nversion: 1\n")
        with self.assertRaisesRegex(ValueError, "重复"):
            module.load_config(path, "node-a")

    def test_invalid_inputs(self):
        cases = [("priority", 255), ("address", "192.168.10.100"), ("address", "10.0.0.1")]
        for key, value in cases:
            data = copy.deepcopy(self.data)
            data["nodes"]["node-a"][key] = value
            with self.subTest(key=key, value=value), self.assertRaises(ValueError):
                self.load(data)
        self.data["health"]["checks"][1]["port"] = 65536
        with self.assertRaises(ValueError):
            self.load()

    def test_quorum_validation(self):
        self.data["health"]["policy"] = "quorum"
        self.data["health"]["min_success"] = 2
        self.assertEqual(self.load()["health"]["min_success"], 2)
        self.data["health"]["min_success"] = 4
        with self.assertRaises(ValueError):
            self.load()

    def test_all_any_quorum(self):
        for policy, threshold, expected in [("all", None, 1), ("any", None, 0), ("quorum", 2, 0), ("quorum", 3, 1)]:
            overrides = {"policy": policy}
            if threshold:
                overrides["min_success"] = threshold
            health = self.health(overrides)
            def fake_worker(check):
                return check["name"], check["type"] != "tcp", "mock"
            health["worker"] = fake_worker
            with contextlib.redirect_stdout(io.StringIO()):
                self.assertEqual(health["main"](), expected)

    def test_process_arguments_and_self_exclusion(self):
        health = self.health()
        result = subprocess.CompletedProcess([], 0, stdout="123\n456\n", stderr="")
        with mock.patch("subprocess.run", return_value=result) as call, mock.patch("os.getpid", return_value=123):
            check = {"type": "process", "match": "cmdline", "pattern": "java.*api.jar", "min_count": 2, "timeout": 1}
            self.assertFalse(health["check_one"](check)[0])
            self.assertEqual(call.call_args.args[0], ["pgrep", "-f", "--", "java.*api.jar"])

    def test_tcp_success_and_exception(self):
        health = self.health()
        check = {"name": "port", "type": "tcp", "host": "127.0.0.1", "port": 8080, "timeout": 0.5}
        with mock.patch("socket.create_connection", return_value=mock.MagicMock()) as call:
            self.assertTrue(health["check_one"](check)[0])
            call.assert_called_once_with(("127.0.0.1", 8080), timeout=0.5)
        with mock.patch("socket.create_connection", side_effect=TimeoutError("mock timeout")):
            result = health["worker"](check)
            self.assertFalse(result[1])
            self.assertIn("Traceback", result[2])

    def test_http_status_body_and_proxy(self):
        health = self.health()
        check = {"type": "http", "url": "http://127.0.0.1/ready", "expected_status": [200], "body_contains": "ready", "timeout": 1}
        response = mock.MagicMock()
        response.__enter__.return_value = response
        response.code = 200
        response.read.return_value = b"ready"
        opener = mock.Mock()
        opener.open.return_value = response
        with mock.patch("urllib.request.build_opener", return_value=opener) as build:
            self.assertTrue(health["check_one"](check)[0])
            self.assertEqual(build.call_args.args[0].proxies, {})
            response.read.assert_called_with(65536)
            response.read.return_value = b"not yet"
            self.assertFalse(health["check_one"](check)[0])
            response.code = 503
            self.assertFalse(health["check_one"](check)[0])

    def test_generated_runtime_and_hard_timeout(self):
        # 可控 worker 替身用于验证真实父进程超时逻辑，不访问网络。
        data = self.load()
        data["health"]["round_timeout"] = 1
        runtime = module.render(data, "node-a", Path("/etc/keepalived"))[1]
        runtime = runtime.replace('def main():\n', 'def main():\n    import time\n    time.sleep(4)\n')
        script = self.directory / "check.py"
        script.write_text(runtime)
        result = subprocess.run([sys.executable, str(script)], capture_output=True, text=True, timeout=3)
        self.assertEqual(result.returncode, 1)
        self.assertIn("整轮健康检查超时", result.stderr)

    def test_check_cli_success_and_failure(self):
        # 只调用目录内的 pgrep 替身，验证生成文件的真实执行链路与退出码。
        binary = self.directory / "pgrep"
        binary.write_text("#!/bin/sh\nprintf '424242\\n'\n")
        binary.chmod(0o700)
        data = copy.deepcopy(self.data)
        data["health"]["checks"] = [data["health"]["checks"][0]]
        config_path = self.directory / "cli.yaml"
        config_path.write_text(yaml.safe_dump(data))
        command = [sys.executable, str(ROOT / "ha-configure.py"), "--config", str(config_path),
                   "--node", "node-a", "--check", "--output-dir", str(self.directory / "generated")]
        environment = dict(os.environ, PATH=str(self.directory) + os.pathsep + os.environ.get("PATH", ""))
        passed = subprocess.run(command, capture_output=True, text=True, env=environment, timeout=10)
        self.assertEqual(passed.returncode, 0, passed.stderr)
        self.assertIn("[PASS] nginx_process", passed.stdout)
        binary.write_text("#!/bin/sh\nexit 1\n")
        failed = subprocess.run(command, capture_output=True, text=True, env=environment, timeout=10)
        self.assertEqual(failed.returncode, 1, failed.stderr)
        self.assertIn("[FAIL] nginx_process", failed.stdout)

    def test_custom_apply_directory_rejected(self):
        with self.assertRaisesRegex(ValueError, "默认"):
            module.apply(None, None, self.directory, {})

    def test_apply_rollback(self):
        # 所有系统命令均模拟，所有文件路径映射到测试目录。
        install_dir = self.directory / "installed"
        install_dir.mkdir()
        (install_dir / "keepalived.conf").write_text("old config")
        staged_config = self.directory / "new.conf"
        staged_config.write_text("new config")
        script = self.directory / "ha-check.py"
        script.write_text("pass\n")
        fake_path = mock.Mock(side_effect=lambda value: install_dir if value == "/etc/keepalived" else Path(value))
        calls = []
        def fake_run(command, **kwargs):
            calls.append(command)
            if command[0] == "ip":
                return subprocess.CompletedProcess(command, 0, stdout='[{"addr_info":[{"local":"192.168.10.11"}]}]')
            if command == ["systemctl", "restart", "keepalived"] and calls.count(command) == 1:
                raise subprocess.CalledProcessError(1, command)
            return subprocess.CompletedProcess(command, 0)
        with mock.patch.object(module, "Path", fake_path), mock.patch.object(module, "run", side_effect=fake_run), \
             mock.patch.object(module.shutil, "which", return_value="mock"), \
             mock.patch.object(module.os, "geteuid", return_value=0), \
             mock.patch.object(module, "sys") as fake_sys, \
             mock.patch("subprocess.run", return_value=subprocess.CompletedProcess([], 0)), \
             mock.patch.object(type(install_dir), "stat", return_value=mock.Mock(st_uid=0, st_mode=0o755)), \
             contextlib.redirect_stdout(io.StringIO()):
            fake_sys.platform = "linux"
            fake_sys.stderr = io.StringIO()
            with self.assertRaises(subprocess.CalledProcessError):
                module.apply(staged_config, script, install_dir, {"interface": "eth0", "address": "192.168.10.11"})
        self.assertEqual((install_dir / "keepalived.conf").read_text(), "old config")
        self.assertEqual(calls.count(["systemctl", "restart", "keepalived"]), 2)


if __name__ == "__main__":
    unittest.main()

--- README ---
# Keepalived 配置工具

本目录提供可直接运行的 Python 工具 `ha-configure.py` 和详细注释示例 `ha.sample.yaml`。部署时拷贝这两份文件即可，README 与 tests 用于说明和开发验证。业务服务不需要注册到 systemd；部署 Keepalived 本身使用 Linux 默认 systemd 服务。

## 依赖

- 生成和校验：Python 3.9+、PyYAML。
- 进程检查：目标机器安装 `pgrep`，Linux 通常由 procps/procps-ng 提供。
- TCP、HTTP 检查：生成脚本使用 Python 标准库，无需 nc/curl。
- 应用：Linux、root、已安装的 keepalived、systemctl、ip；使用 `/etc/keepalived/keepalived.conf` 默认配置。

工具不会自动安装软件。可在本目录创建独立环境，避免污染系统 Python：

```bash
cd output/other/keepalived
python3 -m venv .venv
UV_INDEX_URL=https://pypi.tuna.tsinghua.edu.cn/simple uv pip install --python .venv/bin/python PyYAML
# 使用独立环境时直接通过 .venv/bin/python 调用 ha-configure.py。
```

部署 root 运行时，应使用 root 管理且不可被普通用户写入的 Python 环境。生成配置固定引用生成时的 Python 解释器绝对路径，运行节点上该路径必须持续存在；不要使用随后会删除的临时 venv。

## 使用

```bash
cd output/other/keepalived
cp ha.sample.yaml ha.yaml
# 修改 ha.yaml 中的 VIP、真实地址、网卡和健康检查。
python3 ./ha-configure.py --help
python3 ./ha-configure.py --config ha.yaml --node node-a --dry-run
python3 ./ha-configure.py --config ha.yaml --node node-a --check
sudo python3 ./ha-configure.py --config ha.yaml --node node-a --apply
```

如果使用独立 Python 环境，请直接指定解释器路径：

```bash
sudo /实际/root管理环境/bin/python ./ha-configure.py --config ha.yaml --node node-a --apply
```

另一台机器使用同一 YAML，将 `--node` 改为 `node-b`。每次只作用于本机，不自动通过 SSH 安装其他节点。

## 操作行为

- `--dry-run`：严格校验 YAML，生成文件并打印 Keepalived 配置；不写系统目录，不执行健康请求。
- `--check`：校验、生成，并执行一轮检查；逐项打印结果、异常堆栈及汇总。不需要 Keepalived 已安装。
- `--apply`：确认真实 IP 在指定网卡上，安装健康脚本，运行 Keepalived 配置校验，备份旧配置，再替换并重启。重启失败时恢复旧配置，按原先是否运行恢复/停止服务。
- 配置校验使用兼容旧版本的 `keepalived -t -f <文件>`。如果 Keepalived 自身以 `SIGSEGV`（退出码 139）崩溃，工具不会替换正式配置，会在 `/etc/keepalived/keepalived.conf.config-test-failed-*` 保留失败文件并打印版本信息；此时应升级或更换 Keepalived 二进制，不能跳过校验。
- 生成的 `vrrp_script` 直接执行带绝对 shebang 的健康脚本，不把 Python 解释器拼在 Keepalived 的 `script` 字段中；这样可通过 `enable_script_security` 的脚本路径检查。健康脚本安装为 root 所有、权限 `0700`。
- 应用只检查配置和服务启动，不强制要求当前节点业务健康；备用节点业务暂时不健康时可以安装，是否持有 VIP 交给健康检查。生成的 VIP 使用 `IP/掩码` 的保守写法，不在 `virtual_ipaddress` 行追加 `dev`，因为 VRRP 实例已经声明网卡，兼容较老 Keepalived。
- 默认产物目录：脚本目录 `generated/<node>/`；可用 `--output-dir` 修改。配置中记录的是部署路径，不是产物路径，不能直接拿产物配置启动而漏装健康脚本。
- 健康脚本使用内容哈希命名；旧配置备份仍可引用旧脚本。工具不自动删除旧脚本和备份。
- 不修改防火墙、业务服务、Keepalived 开机启动策略；需要自启时自行执行 `sudo systemctl enable keepalived`。
- 应用会重启 Keepalived，VIP 可能短暂释放；建议先部署备用节点，再在变更窗口部署当前持有 VIP 的节点。
- 不自动合并已有多个 VRRP 实例，替换前请查看备份及预览；自定义 systemd 启动参数的环境需要自行适配。

## 检查规则

详见 `ha.sample.yaml` 中逐字段备注。`all` 要求全部成功；`any` 要求至少一项成功；`quorum` 配合 `min_success` 要求至少 N 项成功。检查并行，单项超时和整轮硬超时都视为失败。

进程匹配为 pgrep 正则；TCP 只证明连接可建立；HTTP 可以同时检查状态码和正文子串。优先用本机 readiness 接口，不要用 VIP 检查备用节点业务。HTTP 禁用代理、不跟随重定向、HTTPS 验证证书。

退出码：`0` 操作成功/检查健康；`1` 检查不健康或整轮超时；`2` 配置/依赖/执行错误；`130` 用户中断。`--check` 只是一轮检查，不累计 `fall/rise`，这些由运行中的 Keepalived 管理。

## 验收与回退

应用后通过 `systemctl status keepalived`、`journalctl -u keepalived` 和 `ip address show dev <网卡>` 确认启动及 VIP 所在节点。服务启动成功不代表健康条件成功或 VIP 一定由本机持有。

旧配置保存在 `/etc/keepalived/keepalived.conf.bak-时间-进程号`；手动回退时将对应备份恢复为 `keepalived.conf` 并重启服务，保留它引用的哈希健康脚本。

当前工具已在开发环境做生成与模拟检查验证；真实双机 VRRP、ARP 与网络故障切换需要在目标 Linux 环境验收。

def fail(message):
    raise ValueError(message)


def mapping(value, where, allowed):
    if not isinstance(value, dict):
        fail("%s 必须是对象" % where)
    unknown = set(value) - set(allowed)
    if unknown:
        fail("%s 存在未知字段：%s" % (where, sorted(map(str, unknown))))
    return value


def number(value, where, minimum, maximum, integer=False):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        fail("%s 必须是有限数字" % where)
    if integer and not isinstance(value, int):
        fail("%s 必须是整数" % where)
    if not minimum <= value <= maximum:
        fail("%s 必须在 %s 到 %s 之间" % (where, minimum, maximum))
    return value


def token(value, where, pattern=r"[A-Za-z0-9_.-]+"):
    if not isinstance(value, str) or not re.fullmatch(pattern, value):
        fail("%s 格式不合法" % where)
    return value


def load_config(path, node_name):
    try:
        import yaml
    except ImportError:
        fail("需要 PyYAML；请在目标 Python 环境中安装，或直接使用包含 PyYAML 的 Python 解释器")
    # 拒绝重复键，避免用户以为两条规则生效，实际后面的覆盖前面的。
    class UniqueLoader(yaml.SafeLoader):
        pass
    def unique_mapping(loader, node, deep=False):
        result = {}
        for key_node, value_node in node.value:
            key = loader.construct_object(key_node, deep=deep)
            if key in result:
                fail("YAML 重复字段：%s" % key)
            result[key] = loader.construct_object(value_node, deep=deep)
        return result
    UniqueLoader.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, unique_mapping)
    data = mapping(yaml.load(path.read_text(encoding="utf-8"), Loader=UniqueLoader),
                   "根配置", ["version", "vrrp", "nodes", "health"])
    if type(data.get("version")) is not int or data["version"] != 1:
        fail("version 必须是整数 1")
    vrrp = mapping(data.get("vrrp"), "vrrp", ["instance", "router_id", "vip", "preempt", "advert_int"])
    token(vrrp.get("instance"), "vrrp.instance")
    number(vrrp.get("router_id"), "vrrp.router_id", 1, 255, True)
    vip = ipaddress.ip_interface(vrrp.get("vip", ""))
    if vip.version != 4 or vip.ip.is_unspecified or vip.ip.is_multicast or vip.ip.is_loopback:
        fail("vrrp.vip 必须是有效的 IPv4 VIP，包含掩码，例如 192.168.10.100/24")
    if "/" not in vrrp["vip"]:
        fail("vrrp.vip 必须显式包含掩码")
    vrrp.setdefault("preempt", False)
    if type(vrrp["preempt"]) is not bool:
        fail("vrrp.preempt 必须是 true 或 false")
    number(vrrp.setdefault("advert_int", 1), "vrrp.advert_int", 1, 60, True)
    nodes = data.get("nodes")
    if not isinstance(nodes, dict) or len(nodes) < 2:
        fail("nodes 至少配置两个节点")
    if node_name not in nodes:
        fail("--node 不在 nodes 中：%s" % node_name)
    addresses = set()
    for name, node in nodes.items():
        token(name, "节点名")
        mapping(node, "nodes." + name, ["address", "interface", "priority"])
        address = ipaddress.ip_address(node.get("address", ""))
        if address.version != 4 or address not in vip.network or address == vip.ip:
            fail("节点 %s 的 IPv4 地址必须与 VIP 同网段且不同于 VIP" % name)
        if address.is_unspecified or address.is_multicast or address.is_loopback:
            fail("节点 %s 地址不合法" % name)
        if str(address) in addresses:
            fail("节点地址不可重复")
        addresses.add(str(address))
        token(node.get("interface"), "节点网卡", r"[A-Za-z0-9_.:-]{1,15}")
        number(node.get("priority"), "节点 priority", 1, 254, True)
    health = mapping(data.get("health"), "health", ["policy", "min_success", "interval", "round_timeout", "fall", "rise", "checks"])
    health.setdefault("policy", "all")
    if health["policy"] not in ("all", "any", "quorum"):
        fail("health.policy 只能为 all、any 或 quorum")
    for field, default in (("interval", 2), ("round_timeout", 5), ("fall", 3), ("rise", 2)):
        number(health.setdefault(field, default), "health." + field, 1, 3600, True)
    checks = health.get("checks")
    if not isinstance(checks, list) or not 1 <= len(checks) <= 16:
        fail("health.checks 必须包含 1 到 16 项检查")
    names = set()
    for check in checks:
        if not isinstance(check, dict):
            fail("每项 checks 必须是对象")
        kind = check.get("type")
        common = ["name", "type", "timeout"]
        fields = {"process": ["match", "pattern", "min_count"], "tcp": ["host", "port"],
                  "http": ["url", "expected_status", "body_contains"]}
        if kind not in fields:
            fail("检查类型只能为 process、tcp、http")
        mapping(check, "检查规则", common + fields[kind])
        token(check.get("name"), "检查名称")
        if check["name"] in names:
            fail("检查名称不可重复")
        names.add(check["name"])
        timeout = number(check.setdefault("timeout", 1), "检查 timeout", 0.1, 3600)
        if timeout >= health["round_timeout"]:
            fail("每项 timeout 必须小于 round_timeout，以预留整轮调度时间")
        if kind == "process":
            check.setdefault("match", "name")
            if check["match"] not in ("name", "cmdline"):
                fail("process.match 只能为 name 或 cmdline")
            if not isinstance(check.get("pattern"), str) or not check["pattern"] or "\x00" in check["pattern"]:
                fail("process.pattern 必须是非空字符串")
            number(check.setdefault("min_count", 1), "process.min_count", 1, 65535, True)
        elif kind == "tcp":
            # 使用 IP 字面量，避免 DNS 解析不受 socket timeout 约束。
            ipaddress.ip_address(check.get("host", "127.0.0.1"))
            check.setdefault("host", "127.0.0.1")
            number(check.get("port"), "tcp.port", 1, 65535, True)
        else:
            url = check.get("url")
            if not isinstance(url, str):
                fail("http.url 必须是字符串")
            parsed = urlsplit(url)
            if parsed.scheme not in ("http", "https") or not parsed.hostname or parsed.username or parsed.password:
                fail("http.url 必须是 HTTP/HTTPS 地址，且不能包含用户名或密码")
            if parsed.fragment or any(char.isspace() for char in url):
                fail("http.url 不能包含空白或 fragment")
            if parsed.port is not None:
                number(parsed.port, "http URL 端口", 1, 65535, True)
            statuses = check.setdefault("expected_status", [200])
            if not isinstance(statuses, list) or not statuses:
                fail("http.expected_status 必须是非空数组")
            for status in statuses:
                number(status, "HTTP 状态码", 100, 599, True)
            if "body_contains" in check and (not isinstance(check["body_contains"], str) or not check["body_contains"]):
                fail("http.body_contains 必须是非空字符串")
    if health["policy"] == "quorum":
        number(health.get("min_success"), "health.min_success", 1, len(checks), True)
    elif "min_success" in health:
        fail("min_success 仅可用于 quorum 策略")
    return data


def render(data, node_name, install_dir):
    health = data["health"]
    spec = {key: health[key] for key in ("policy", "round_timeout", "checks")}
    if "min_success" in health:
        spec["min_success"] = health["min_success"]
    node, vrrp = data["nodes"][node_name], data["vrrp"]
    # 健康脚本由 Keepalived 直接执行；绝对 shebang 避免 daemon 的 PATH 与交互 shell 不同。
    python_path = str(Path(sys.executable).resolve())
    for value in (python_path, str(install_dir)):
        if not re.fullmatch(r"/[A-Za-z0-9_./-]+", value):
            fail("解释器或安装目录路径不支持空格及特殊字符：%s" % value)
    runtime = "#!" + python_path + "\n# 自动生成：本机服务健康检查，修改源 YAML 后重新生成。\nSPEC = " + repr(spec) + "\n" + HEALTH_PROGRAM
    digest = hashlib.sha256(runtime.encode()).hexdigest()[:16]
    script_name = "ha-check-" + digest + ".py"
    peers = "\n".join("        " + item["address"] for name, item in data["nodes"].items() if name != node_name)
    config = f'''# 自动生成：节点 {node_name}。健康脚本 weight 0，失败进入 FAULT。
# 所有节点初始 state BACKUP，便于 nopreempt 生效。
global_defs {{
    router_id {node_name}
    script_user root
    enable_script_security
}}

vrrp_script ha_health {{
    script "{install_dir / script_name} --quiet"
    interval {health['interval']}
    timeout {health['round_timeout'] + 2}
    fall {health['fall']}
    rise {health['rise']}
    weight 0
    init_fail
}}

vrrp_instance {vrrp['instance']} {{
    state BACKUP
    interface {node['interface']}
    virtual_router_id {vrrp['router_id']}
    priority {node['priority']}
    advert_int {vrrp['advert_int']}
    {'# 恢复后允许抢占' if vrrp['preempt'] else 'nopreempt'}
    unicast_src_ip {node['address']}
    unicast_peer {{
{peers}
    }}
    virtual_ipaddress {{
        {vrrp['vip']}
    }}
    track_script {{
        ha_health
    }}
}}
'''
    return config, runtime, script_name


def run(command, **kwargs):
    import shlex
    print("$ " + shlex.join(command), flush=True)
    return subprocess.run(command, check=True, timeout=30, **kwargs)


def apply(config_path, script_path, install_dir, node):
    if install_dir != Path("/etc/keepalived"):
        fail("--apply 仅支持默认 /etc/keepalived；自定义目录请先生成，再按实际服务启动参数手动部署")
    if sys.platform != "linux" or os.geteuid() != 0:
        fail("--apply 需要在 Linux 上以 root 运行；当前环境可以使用 --dry-run")
    for binary in ("keepalived", "systemctl", "ip"):
        if not shutil.which(binary):
            fail("--apply 缺少依赖：%s，请先安装" % binary)
    # 应用前确认配置中的源地址确实绑定在本机指定网卡上。
    addresses = json.loads(run(["ip", "-j", "address", "show", "dev", node["interface"]], capture_output=True, text=True).stdout)
    if not any(item.get("local") == node["address"] for interface in addresses for item in interface.get("addr_info", [])):
        fail("节点 address 未绑定在本机配置的 interface 上")
    if install_dir.exists():
        if install_dir.is_symlink() or install_dir.stat().st_uid != 0 or install_dir.stat().st_mode & 0o022:
            fail("安装目录必须由 root 所有，且不可被组或其他用户写入")
    else:
        install_dir.mkdir(parents=True, mode=0o755)
    # 健康脚本采用内容哈希命名，旧配置始终引用旧脚本；失败恢复时不混用版本。
    installed_script = install_dir / script_path.name
    if installed_script.exists() and installed_script.is_symlink():
        fail("健康脚本路径不可为符号链接")
    shutil.copyfile(script_path, installed_script)
    installed_script.chmod(0o700)
    target = install_dir / "keepalived.conf"
    if target.is_symlink():
        fail("keepalived.conf 不可为符号链接")
    staged = install_dir / (".ha-config-%d.conf" % os.getpid())
    backup = None
    was_active = subprocess.run(["systemctl", "is-active", "--quiet", "keepalived"], timeout=10).returncode == 0
    try:
        shutil.copyfile(config_path, staged)
        staged.chmod(0o600)
        try:
            run(["keepalived", "-t", "-f", str(staged)])
        except subprocess.CalledProcessError as error:
            failed = install_dir / ("keepalived.conf.config-test-failed-%s-%d" % (time.strftime("%Y%m%d-%H%M%S"), os.getpid()))
            shutil.copy2(staged, failed)
            version = subprocess.run(["keepalived", "--version"], capture_output=True, text=True, timeout=10)
            if error.returncode < 0:
                signal_number = -error.returncode
                reason = "Keepalived 配置校验被信号 %d 终止（可能是旧版本/发行版二进制崩溃）" % signal_number
            else:
                reason = "Keepalived 配置校验失败，退出码 %d" % error.returncode
            print("[apply] %s；失败配置已保留：%s\nKeepalived 版本信息：\n%s" %
                  (reason, failed, version.stdout.strip() or version.stderr.strip() or "(无版本输出)"),
                  file=sys.stderr)
            raise
        if target.exists():
            backup = install_dir / ("keepalived.conf.bak-%s-%d" % (time.strftime("%Y%m%d-%H%M%S"), os.getpid()))
            shutil.copy2(target, backup)
            print("旧配置备份：%s" % backup)
        os.replace(staged, target)
        try:
            # 重启可完整应用 VRRP 与脚本变化；会短暂释放 VIP，执行前应安排变更窗口。
            run(["systemctl", "restart", "keepalived"])
            run(["systemctl", "is-active", "--quiet", "keepalived"])
        except Exception:
            print("[apply] 启动失败，恢复旧配置：\n" + traceback.format_exc(), file=sys.stderr)
            if backup:
                shutil.copy2(backup, target)
            else:
                target.unlink(missing_ok=True)
            if was_active:
                run(["systemctl", "restart", "keepalived"])
            else:
                run(["systemctl", "stop", "keepalived"])
            raise
            raise
    finally:
        staged.unlink(missing_ok=True)
    print("应用完成。未修改开机启动策略；如需自启，请执行 systemctl enable keepalived。")


def main():
    parser = argparse.ArgumentParser(
        description="从 YAML 一键生成/校验/应用 Keepalived。健康检查支持进程、TCP、HTTP。",
        epilog="示例：\n  python3 ./ha-configure.py --config ha.sample.yaml --node node-a --dry-run\n"
               "  python3 ./ha-configure.py --config ha.yaml --node node-a --check\n"
               "  sudo python3 ./ha-configure.py --config ha.yaml --node node-a --apply\n"
               "退出码：0=成功，1=健康检查失败/整轮超时，2=配置或执行错误。\n"
               "--apply 会替换整个 keepalived.conf 并重启服务（VIP 可能短暂释放）；自动备份及失败恢复。\n"
               "依赖：Python 3.9+、PyYAML；应用需 Linux、root、已安装 keepalived 和 systemd。",
        formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--version", action="version", version="%(prog)s 1.0.0")
    parser.add_argument("--config", type=Path, required=True, help="YAML 配置文件（必填）")
    parser.add_argument("--node", required=True, help="当前节点名，必须存在于 nodes 中（必填）")
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--check", action="store_true", help="校验配置并执行一次本机健康检查，不应用系统配置")
    mode.add_argument("--dry-run", action="store_true", help="生成配置与检查脚本并打印配置，不应用系统配置")
    mode.add_argument("--apply", action="store_true", help="校验后备份、安装并重启；不自动安装软件")
    parser.add_argument("--output-dir", type=Path, default=Path(__file__).resolve().parent / "generated", help="生成目录（默认：脚本目录/generated/<node>）")
    parser.add_argument("--install-dir", type=Path, default=Path("/etc/keepalived"), help="生成配置中引用的安装目录（默认：/etc/keepalived；自定义目录仅支持预览/检查）")
    args = parser.parse_args()
    data = load_config(args.config, args.node)
    config, runtime, script_name = render(data, args.node, args.install_dir.resolve())
    destination = args.output_dir.resolve() / args.node
    destination.mkdir(parents=True, exist_ok=True)
    config_path = destination / "keepalived.conf"
    script_path = destination / script_name
    config_path.write_text(config, encoding="utf-8")
    script_path.write_text(runtime, encoding="utf-8")
    script_path.chmod(0o700)
    print("配置校验通过；生成目录：%s" % destination, flush=True)
    if args.check:
        return subprocess.run([sys.executable, str(script_path)], timeout=data["health"]["round_timeout"] + 3).returncode
    if args.dry_run:
        print(config)
        print("未写入系统目录。部署时请将健康脚本与 keepalived.conf 一起安装。")
    else:
        apply(config_path, script_path, args.install_dir.resolve(), data["nodes"][args.node])
    return 0


if __name__ == "__main__":
    if sys.version_info < (3, 9):
        sys.exit("需要 Python 3.9 或更高版本")
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        print("操作已中断", file=sys.stderr)
        sys.exit(130)
    except Exception:
        print("[main] 配置或执行错误：\n" + traceback.format_exc(), file=sys.stderr)
        sys.exit(2)
"""配置生成与健康判断测试；网络与系统服务调用均为模拟。"""
import contextlib
import copy
import importlib.util
import io
import os
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest
from unittest import mock
import yaml

ROOT = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location("ha_configure", ROOT / "ha-configure.py")
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)


class HaTests(unittest.TestCase):
    def setUp(self):
        self.local = ROOT / ".local"
        self.local.mkdir(exist_ok=True)
        self.temp = tempfile.TemporaryDirectory(dir=self.local)
        self.addCleanup(self.temp.cleanup)
        self.directory = Path(self.temp.name)
        self.data = yaml.safe_load((ROOT / "ha.sample.yaml").read_text())

    def load(self, data=None):
        path = self.directory / "ha.yaml"
        path.write_text(yaml.safe_dump(self.data if data is None else data))
        return module.load_config(path, "node-a")

    def health(self, overrides=None):
        spec = {"policy": "all", "round_timeout": 2, "checks": self.load()["health"]["checks"]}
        spec.update(overrides or {})
        namespace = {"__name__": "health_test", "SPEC": spec}
        exec(compile(module.HEALTH_PROGRAM, "health.py", "exec"), namespace)
        return namespace

    def test_nodes_and_nopreempt(self):
        data = self.load()
        config, runtime, name = module.render(data, "node-a", Path("/etc/keepalived"))
        self.assertIn("unicast_src_ip 192.168.10.11", config)
        self.assertIn("        192.168.10.12", config)
        self.assertIn("nopreempt", config)
        self.assertIn("weight 0", config)
        self.assertIn("init_fail", config)
        self.assertIn(name, config)
        self.assertIn("script \"/etc/keepalived/" + name + " --quiet\"", config)
        self.assertTrue(runtime.startswith("#!" + str(Path(module.sys.executable).resolve())))
        self.assertIn("        192.168.10.100/24\n", config)
        self.assertNotIn("192.168.10.100/24 dev eth0", config)
        compile(runtime, name, "exec")
        backup = module.render(data, "node-b", Path("/etc/keepalived"))[0]
        self.assertIn("priority 100", backup)
        self.assertIn("        192.168.10.11", backup)

    def test_three_nodes_equal_priority(self):
        self.data["nodes"]["node-a"]["priority"] = 100
        self.data["nodes"]["node-c"] = {
            "address": "192.168.10.13", "interface": "eth0", "priority": 100}
        data = self.load()
        for name in data["nodes"]:
            config = module.render(data, name, Path("/etc/keepalived"))[0]
            self.assertIn("    priority 100\n", config)
            for peer_name, peer in data["nodes"].items():
                if peer_name != name:
                    self.assertIn("        " + peer["address"] + "\n", config)

    def test_preempt(self):
        self.data["vrrp"]["preempt"] = True
        self.assertNotIn("    nopreempt\n", module.render(self.load(), "node-a", Path("/etc/keepalived"))[0])

    def test_unknown_field(self):
        self.data["health"]["falls"] = 3
        with self.assertRaises(ValueError):
            self.load()

    def test_duplicate_yaml_keys(self):
        path = self.directory / "duplicate.yaml"
        path.write_text("version: 1\nversion: 1\n")
        with self.assertRaisesRegex(ValueError, "重复"):
            module.load_config(path, "node-a")

    def test_invalid_inputs(self):
        cases = [("priority", 255), ("address", "192.168.10.100"), ("address", "10.0.0.1")]
        for key, value in cases:
            data = copy.deepcopy(self.data)
            data["nodes"]["node-a"][key] = value
            with self.subTest(key=key, value=value), self.assertRaises(ValueError):
                self.load(data)
        self.data["health"]["checks"][1]["port"] = 65536
        with self.assertRaises(ValueError):
            self.load()

    def test_quorum_validation(self):
        self.data["health"]["policy"] = "quorum"
        self.data["health"]["min_success"] = 2
        self.assertEqual(self.load()["health"]["min_success"], 2)
        self.data["health"]["min_success"] = 4
        with self.assertRaises(ValueError):
            self.load()

    def test_all_any_quorum(self):
        for policy, threshold, expected in [("all", None, 1), ("any", None, 0), ("quorum", 2, 0), ("quorum", 3, 1)]:
            overrides = {"policy": policy}
            if threshold:
                overrides["min_success"] = threshold
            health = self.health(overrides)
            def fake_worker(check):
                return check["name"], check["type"] != "tcp", "mock"
            health["worker"] = fake_worker
            with contextlib.redirect_stdout(io.StringIO()):
                self.assertEqual(health["main"](), expected)

    def test_process_arguments_and_self_exclusion(self):
        health = self.health()
        result = subprocess.CompletedProcess([], 0, stdout="123\n456\n", stderr="")
        with mock.patch("subprocess.run", return_value=result) as call, mock.patch("os.getpid", return_value=123):
            check = {"type": "process", "match": "cmdline", "pattern": "java.*api.jar", "min_count": 2, "timeout": 1}
            self.assertFalse(health["check_one"](check)[0])
            self.assertEqual(call.call_args.args[0], ["pgrep", "-f", "--", "java.*api.jar"])

    def test_tcp_success_and_exception(self):
        health = self.health()
        check = {"name": "port", "type": "tcp", "host": "127.0.0.1", "port": 8080, "timeout": 0.5}
        with mock.patch("socket.create_connection", return_value=mock.MagicMock()) as call:
            self.assertTrue(health["check_one"](check)[0])
            call.assert_called_once_with(("127.0.0.1", 8080), timeout=0.5)
        with mock.patch("socket.create_connection", side_effect=TimeoutError("mock timeout")):
            result = health["worker"](check)
            self.assertFalse(result[1])
            self.assertIn("Traceback", result[2])

    def test_http_status_body_and_proxy(self):
        health = self.health()
        check = {"type": "http", "url": "http://127.0.0.1/ready", "expected_status": [200], "body_contains": "ready", "timeout": 1}
        response = mock.MagicMock()
        response.__enter__.return_value = response
        response.code = 200
        response.read.return_value = b"ready"
        opener = mock.Mock()
        opener.open.return_value = response
        with mock.patch("urllib.request.build_opener", return_value=opener) as build:
